# Prefer an app-owned writable folder rather than the extracted ZIP folder.
def choose_data_dir() -> Path:
    candidates = []
    env_dir = os.environ.get('ANBAR_DATA_DIR')
    if env_dir: candidates.append(Path(env_dir).expanduser())
    try: candidates.append(Path.home() / 'AnbarElectronicData')
    except Exception: pass
    candidates.append(Path(__file__).resolve().parent / 'data')
    try: candidates.append(Path(tempfile.gettempdir()) / f'anbar_electronic_{os.getuid() if hasattr(os, "getuid") else "user"}')
    except Exception: pass
    errors=[]
    for folder in candidates:
        try:
            folder.mkdir(parents=True, exist_ok=True)
            probe=folder / f'.write_check_{uuid.uuid4().hex}'
            probe.write_text('ok', encoding='utf-8'); probe.unlink()
            return folder.resolve()
        except OSError as exc:
            errors.append(f'{folder}: {exc}')
    raise OSError('هیچ پوشه قابل نوشتنی برای ذخیره اطلاعات پیدا نشد. ' + ' | '.join(errors))

DATA_DIR = choose_data_dir()
DB_PATH = DATA_DIR / 'inventory.db'

